nodes.statement:
The expectation value of function $f$ on $\finset{X}$ is defined as
$\expec{x \leftarrow X}{f(x)} \ensuremath{ \stackrel{\mathrm{def}}{=} } \sum_{x \in \finset{X}} \prob{X=x}
\cdot f(x),$ where $x\leftarrow X$ means that $x$ is drawn according to distribution $X$.

For states $\rho$, $\sigma \in \mathcal{D}(A)$, and quantum operation $\mathcal{E}(\cdot):\mathcal{L}(A)\rightarrow \mathcal{L}(B)$, it holds that
\begin{align*}
	\onenorm{\mathcal{E}(\rho) - \mathcal{E}(\sigma)} \leq \onenorm{\rho - \sigma} \quad \mbox{and} \quad \mathrm{F}(\mathcal{E}(\rho),\mathcal{E}(\sigma)) \geq \mathrm{F}(\rho,\sigma) \quad \mbox{and} \quad \relent{\rho}{\sigma}\geq \relent{\mathcal{E}(\rho)}{\mathcal{E}(\sigma)}.
\end{align*}
In particular, for bipartite states $\rho^{AB},\sigma^{AB}\in \mathcal{D}(AB)$, it holds that
\begin{align*}
	\onenorm{\rho^{AB} - \sigma^{AB}} \geq \onenorm{\rho^A - \sigma^A} \quad \mbox{and} \quad \mathrm{F}(\rho^{AB},\sigma^{AB}) \leq \mathrm{F}(\rho^A,\sigma^A) \quad \mbox{and} \quad \relent{\rho_{AB}}{\sigma_{AB}}\geq \relent{\rho_A}{\sigma_A} .
\end{align*}

Consider, 
\begin{eqnarray*}
\ensuremath{ \mathrm{Tr} }(e^{\text{log}(\sigma_{AB})-\text{log}(\sigma_{A}\otimes I_B)+\text{log}(\rho_{A}\otimes I_B)}) &<& \int_{0}^{\infty}du\ensuremath{ \mathrm{Tr} }(\sigma_{AB}\frac{1}{\sigma_A+uI_A}\rho_A\frac{1}{\sigma_A+uI_A}) \quad (\text{Theorem} 5, ~\cite{ruskai2002} ) \\ 
&=&  \int_{0}^{\infty}du\ensuremath{ \mathrm{Tr} }(\frac{1}{\sigma_A+uI_A}\sigma_{A}\frac{1}{\sigma_A+uI_A}\rho_A) \\
&=& \ensuremath{ \mathrm{Tr} }(\sigma_{A}\int_{0}^{\infty}du\frac{1}{(\sigma_A+uI_A)^2}\rho_A) = \ensuremath{ \mathrm{Tr} }(\sigma_A\sigma^{-1}_A\rho_A) =1.
\end{eqnarray*}

Consider,
\begin{eqnarray*}
\condmutinf{A_1A_2\ldots A_k}{B}{C}_{\rho}&=&\condmutinf{A_1}{B}{C}_{\rho}+\condmutinf{A_2A_3\ldots A_k}{B}{A_1C}_\rho\\
&=&\condmutinf{A_1}{B}{C}_{\rho}+\mutinf{A_2A_3\ldots A_k}{A_1BC}_{\rho}-\mutinf{A_1}{A_2A_3\ldots A_k}\rho\\
&=&\condmutinf{A_1}{B}{C}_{\rho}+\mutinf{A_2A_3\ldots A_k}{A_1BC}_{\rho}\\
&\geq&\condmutinf{A_1}{B}{C}_{\rho}+\condmutinf{A_2A_3\ldots A_k}{B}{C}_{\rho}
\end{eqnarray*}
The first and second equalities follow from the definition of the conditional mutual information. The third equality is from the independence between $A_1$ and $A_2A_3\ldots A_k$. The last inequality is from strong subadditivity (Fact~\ref{fact:strongsubadditivity}). Proof follows by induction.

Let the eigen-decomposition of $\rho$ be $\sum_{i=1}^Na_i\ketbra{a_i}$ and that of $\sigma$ be $\sum_{i=1}^Nb_i\ketbra{b_i}$. Define $c\ensuremath{ \stackrel{\mathrm{def}}{=} }\relent{\rho}{\sigma}$, $\delta \ensuremath{ \stackrel{\mathrm{def}}{=} } ({\varepsilon}/3)^4$ and $c' \ensuremath{ \stackrel{\mathrm{def}}{=} } (c+2)/\delta$. Without loss of generality, assume $a_1,a_2\ldots a_N, \frac{2^{c'}}{\delta}b_1,\frac{2^{c'}}{\delta}b_2\ldots \frac{2^{c'}}{\delta}b_N$ to be rational numbers, and define $K$ be the least common multiple of their denominators. The error due to this assumption can be made arbitrarily close to $0$, for large enough $K$.  

Let $\set{\ket{1},\ket{2}\ldots \ket{N}}$ be an orthonormal basis for $\CMcal{H}$. Introduce registers $A_1,B_1$ associated to $\CMcal{H}$ and registers $A_2,B_2$ associated to some Hilbert space $\CMcal{H}'$ with an orthonormal basis $\set{\ket{1},\ket{2}\ldots \ket{K}}$.

Consider the following state on $A_1,A_2,B_1,B_2$. 
\begin{equation} \ket{S}_{A_1A_2B_1B_2} \ensuremath{ \stackrel{\mathrm{def}}{=} } \frac{1}{\sqrt{KN}}\sum_{i=1}^N \ket{i,i}_{A_1B_1} \otimes \left( \sum_{m=1}^{K}\ket{m, m}_{A_2B_2} \right)
\end{equation}

For brevity, define registers $A,B$ such that $A\ensuremath{ \stackrel{\mathrm{def}}{=} } A_1A_2$ and $B\ensuremath{ \stackrel{\mathrm{def}}{=} } B_1B_2$.

The protocol is described below.

\begin{mdframed}
\bigskip
\textbf{Input:} Alice is given $\rho=\sum_{i=1}^Na_i\ketbra{a_i}$. Bob is given $\sigma=\sum_{i=1}^Nb_i\ketbra{b_i}$.
\bigskip



\textbf{Shared resources:} Alice and Bob hold $\lceil N\log(\frac{1}{\delta}) \rceil$ registers $A_1^iA_2^iB_1^iB_2^i$ ($i \in [\lceil N\log(\frac{1}{\delta}) \rceil]$), such that $A_1^i\equiv A_1, A^i_2\equiv A_2, B_1^i\equiv B_1,B_2^i\equiv B_2$. The shared state in register $A_1^iA_2^iB_1^iB_2^i$ is $\ket{S}_{A_1^iA_2^iB_1^iB_2^i}$. Let $i$ refer to the `index' of corresponding registers.

They also share infinitely many random hash functions $h_1,h_2,\cdots$, where each $h_l:\set{0,\cdots,N-1}\rightarrow\set{0,1}$.

\begin{enumerate}

\item \textbf{For} $i=1$ to $\lceil N\log(\frac{1}{\delta}) \rceil$,

\begin{enumerate}

\item Alice performs the measurement $\set{P_A,I_A- P_A}$ on each register $A_1^iA^i_2$ where,
\begin{equation} P_A\ensuremath{ \stackrel{\mathrm{def}}{=} }\sum_i\ket{a_i}_{A_1}\bra{a_i}_{A_1}\otimes\left(\sum_{m=1}^{Ka_i}\ket{m}_{A_2}\bra{m}_{A_2}\right) .
\end{equation}

On each index $i$, she declares \textit{success} if her outcome corresponds to $P_A$.

\item Bob performs the measurement $\set{P_B,I_B- P_B}$ on each register $B_1^iB^i_2$ where,
\begin{equation} P_B\ensuremath{ \stackrel{\mathrm{def}}{=} } \sum_i\ket{b_i}_{B_1}\bra{b_i}_{B_1}\otimes\left(\sum_{m=1}^{\min\{\frac{K}{\delta} 2^{c'} b_i,K\}}\ket{m}_{B_2}\bra{m}_{B_2}\right) .
\end{equation}

On each index $i$, he declares \textit{success} if his outcome corresponds to $P_B$.
\end{enumerate}

\textbf{Endfor}

\item If Alice does not succeed on any index, she aborts.

\item Else, Alice selects the first index $m$ where she succeeds and sends to Bob the binary encoding of $k=\lceil m/N\rceil$ using $\lceil\log\log\frac{1}{\delta}\rceil$ bits.  

\item Alice sends $\{ h_l(m\mod N) |~ l \in  [\lceil r + 2\log\frac{1}{\delta}\rceil]\}$  to Bob.

\item  Define $S_B \ensuremath{ \stackrel{\mathrm{def}}{=} } \{ t |~ \text{ Bob succeeds on index } $t$\} \cap \{(k-1)N,  \cdots, k N -1\}$. If $S_B$ is empty, he outputs $\ketbra{0}$. Bob selects the first index $n$ in $S_B$ such that $\forall l \in  [\lceil r + 2\log\frac{1}{\delta}\rceil]: h_l(n \mod N) = h_l(m \mod N) $ and outputs the state in $B_1^n$ (if no such index exists, he outputs $\ketbra{0}$).  

\end{enumerate}

\end{mdframed}
\bigskip

We analyze the protocol through a series of claims. 
Following claim computes the probability of success for Alice and Bob.

\begin{claim} For each index $i$, $\prob{\text{Alice succeeds}}=\frac{1}{N}$; $\prob{\text{Bob succeeds}}\leq\frac{2^{c'}}{\delta N}$
\end{claim}

\begin{proof}
Follows from direct calculation.
\end{proof}

From quantum substrate theorem (Fact \ref{fact:substrate}), there exists a state $\rho'$ which satisfies $\mathrm{F}(\rho,\rho')\geq 1-\delta$ and $$\rminent{\rho'}{\sigma}\leq\frac{\relent{\rho}{\sigma}+1}{\delta}+\log\frac{1}{1-\delta}\leq \frac{\relent{\rho}{\sigma}+2}{\delta}=c'.$$ We prove the following claim which is of independent interest as well. 
\begin{claim} Let $\rho'$ have the eigen-decomposition $\rho' = \sum_i g_i\ket{g_i}\bra{g_i}$. For any $p>0$ and every $\ket{g_i}\bra{g_i}$, we have $\sum_{j|~b_j\leq p\cdot g_i}\abs{\braket{b_j}{g_i}}^2 \leq 2^{c'}\cdot p$.
\end{claim}
\begin{proof}
Since  $\rho' \leq 2^{c'}\sigma$, it implies $g_i\ket{g_i}\bra{g_i} \leq 2^{c'}\sigma$. Let $\Pi$ be the projection onto the eigen-space of $\sigma$ with eigenvalues less than or equal to $p\cdot g_i$. We have $\Pi\sigma\Pi \leq p\cdot g_i\cdot\Pi$. After applying $\Pi$ on both sides of the equation $g_i\ket{g_i}\bra{g_i} \leq 2^{c'}\sigma$ and taking operator norm on both sides, we get $g_i\sum_{j:~b_j \leq p\cdot g_i}\abs{\braket{b_j}{g_i}}^2 \leq 2^{c'}\cdot p \cdot g_i $. This implies the lemma. 
\end{proof}

Define 
$$\ket{S_A(\rho)}\ensuremath{ \stackrel{\mathrm{def}}{=} } \frac{1}{\sqrt{K}}\sum_{i=1}^N\ket{a_i}\ket{\conjugate{a_i}}\otimes \left(\sum_{m=1}^{Ka_i}\ket{m, m}\right) ; $$
$$\ket{S_A(\rho')}\ensuremath{ \stackrel{\mathrm{def}}{=} }\frac{1}{\sqrt{K}}\sum_{i=1}^N\ket{g_i}\ket{\conjugate{g_i}}\otimes \left(\sum_{m=1}^{\lceil Kg_i \rceil}\ket{m, m} \right) .$$
Here $\ket{\conjugate{a_i}}$ (similarly $\ket{\conjugate{g_i}}$) is the state obtained by taking complex conjugate of  $\ket{a_i}$ ($\ket{g_i}$), with respect to the basis $\set{\ket{1},\ket{2}\ldots \ket{N}}$ in $\CMcal{H}$.  

The following claim asserts that $\ket{S_A(\rho)}$ and $\ket{S_A(\rho')}$ are close if $\rho$ and $\rho'$ are close.
\begin{claim} $\abs{\braket{S_A(\rho)}{S_A(\rho')}} \geq 1- 2 (1-\mathrm{F}(\rho,\rho'))^{1/4} .$
\end{claim}
\begin{proof}
Define $R_{ij}\ensuremath{ \stackrel{\mathrm{def}}{=} } a_i \abs{\braket{a_i}{g_j}}^2$ and $R'_{ij}\ensuremath{ \stackrel{\mathrm{def}}{=} } g_i \abs{\braket{a_i}{g_j}}^2$. Note that both $R \ensuremath{ \stackrel{\mathrm{def}}{=} } \{R_{ij}\}$ and $R' \ensuremath{ \stackrel{\mathrm{def}}{=} } \{R'_{ij}\}$ form probability distributions over $[N^2]$. Also note that $\mathrm{F}(R,R') = \ensuremath{ \mathrm{Tr} }(\sqrt{\rho}\sqrt{\rho'})$. Consider
\begin{align*}
 \abs{\braket{S_A(\rho)}{S_A(\rho')}} & =\sum_{i,j}\min(R_{ij},R'_{i,j}) = 1 - \frac{1}{2}\onenorm{R-R'} \nonumber\\
 & \geq 1 - \sqrt{1-\mathrm{F}(R,R')^2} = 1 - \sqrt{1-(\ensuremath{ \mathrm{Tr} } \sqrt{\rho}\sqrt{\rho'})^2} \nonumber \\
 & \geq 1 - \sqrt{2(1- \ensuremath{ \mathrm{Tr} } \sqrt{\rho}\sqrt{\rho'})} \geq  1- \sqrt{2 \sqrt{1-\mathrm{F}(\rho,\rho')^2}}  \nonumber \\
 & \geq 1- 2 (1-\mathrm{F}(\rho,\rho'))^{1/4} . \tag*{\qedhere} 
  \end{align*}
where the first equality is from the definitions of $\ket{S_A(\rho)}$ and $\ket{S_A(\rho')}$; the second equality is from the definition of $\ell_1$ distance; the first inequality is from ~\ref{fact:tracefidelityequi}; the second inequality is from the fact that $\ensuremath{ \mathrm{Tr} }\sqrt{\rho}\sqrt{\rho'}\leq 1$; the third inequality is from Facts~\ref{fact:fidelityvstrace}.
\end{proof}
We use these claims to prove the following.
\begin{claim} For each index $i$, $\prob{\text{Bob succeeds}|~\text{Alice succeeds}}\geq 1 - \delta -  2 \delta^{1/4} \geq 1 - {\varepsilon} $.
\end{claim}

\begin{proof}
Consider,
\begin{equation*}
(I_A\otimes P_B)\ket{S_A(\rho')} = \frac{1}{\sqrt{K}}\sum_{i,j=1}^N\ket{\conjugate{g_j}} \ket{b_i}\braket{b_i}{g_j} \left(\sum_{m=1}^{\min\{\lceil Kg_j\rceil, \frac{K}{\delta} 2^{c'}b_i\}}\ket{m, m} \right).
\end{equation*}
Therefore,
\begin{align}
& \norm{(I_A\otimes P_B)\ket{S_A(\rho')} }^2 \geq \sum_{i,j=1}^N \abs{\braket{b_i}{g_j}}^2 \min\{g_j, \frac{1}{\delta}2^{c'}b_i \} \nonumber \\
& \geq \sum_{j=1}^N g_j \left(\sum_{i|~b_i\geq \delta 2^{-c'}g_j} \abs{\braket{b_i}{g_j}}^2 \right) \geq \sum_{j=1}^N g_j(1- \delta) = 1- \delta  . \quad \mbox{(using Claim~\ref{claim:1})} \end{align}
Using the above,

\begin{align*}
& \prob{\text{Bob succeeds}|~\text{Alice succeeds}}  =  \ensuremath{ \mathrm{Tr} } (I_A\otimes P_B)\ketbra{S_A(\rho)} \\
& \geq  \ensuremath{ \mathrm{Tr} } (I_A\otimes P_B)\ketbra{S_A(\rho')}  - \frac{1}{2} \onenorm{S_A(\rho) - S_A(\rho')} \\
& = \ensuremath{ \mathrm{Tr} } (I_A\otimes P_B)\ketbra{S_A(\rho')}  -  \sqrt{1- \abs{\braket{S_A(\rho)}{S_A(\rho')}}^2} \quad \mbox{(Fact~\ref{fact:tracefidelityequi})} \\
& \geq  1 -  \delta  - 2  \sqrt{ (1-\mathrm{F}(\rho,\rho'))^{1/2}}  . \quad \mbox{(Claim~\ref{claim:2} and Eq.~\eqref{eq:probonrho'})}
\end{align*}
\end{proof}

Finally, we show that if Alice and Bob succeed together on an index, the state in register $B$ with Bob is close to $\rho$.
\begin{claim} Given that both Alice and Bob succeed, fidelity between $\rho$ and the state of the register $B$ is at least $\sqrt{1 - \delta -  2 \delta^{1/4}} \geq 1 - {\varepsilon} $ .
\end{claim}

\begin{proof}
From gentle measurement lemma (Fact~\ref{fact:gentlemeasurement}), 
$$\mathrm{F}(S_A(\rho), \frac{(I_A\otimes P_B)\ketbra{S_A(\rho)} (I_A\otimes P_B) }{\ensuremath{ \mathrm{Tr} } (I_A\otimes P_B)\ketbra{S_A(\rho)}}) \geq \sqrt{\ensuremath{ \mathrm{Tr} } (I_A\otimes P_B)\ketbra{S_A(\rho)}}. $$ 
Since the marginal of $\ket{S_A(\rho)}$ on  register $B$ is $\rho$ and partial trace does not decrease fidelity (Fact~\ref{fact:monotonequantumoperation}), using item 2. above, the desired result follows. 

\end{proof}

Let $j$ be the first index where Alice and Bob both succeed. As described in the protocol, $m$ is the first index where Alice succeeds and $n$ is the index such that Bob outputs the state in $B_1^n$. 
We have the following claim, 

\begin{claim} With probability at least $1-4{\varepsilon}$, $m=n=j$.
\end{claim}

Before proving Claim~\ref{claim:highprobindex}, let us define the following "bad" events.
\begin{definition} \begin{itemize}

\item $T_1$ is the event that Alice does not succeed on any of the indices.

\item $T_2$ is the event that $m \notin S_B$ conditioned on $\neg T_1$ .
\item $T_3$ represents the event that $n \neq m$ conditioned on $\neg T_1$.
\end{itemize}
\end{definition}

Notice that if none of above events occur, then both Alice and Bob output the same index $n=m$, and since $m$ is the first index at which Alice succeeds, $n=m=j$. 

We have the following claim.

\begin{claim} It holds that: \quad $1. ~ \prob{T_1}\leq {\varepsilon}; \quad 2. ~ \prob{T_2}\leq{\varepsilon}; \quad 3. ~ \prob{T_3}\leq3{\varepsilon}.$
\end{claim}
\begin{proof}

\begin{enumerate}

\item $\prob{T_1}\leq\br{1-\frac{1}{N}}^{\lceil N \cdot \log\frac{1}{{\varepsilon}}\rceil}\leq \exp^{-\lceil\log\frac{1}{{\varepsilon}}\rceil}\leq  \delta$.

\item Follows from Claim \ref{claim:relativeprob}.

\item For this argument we condition on $\neg T_1$ for all events below. From Claim \ref{claim:successprob} and the fact that Bob independently measures each index, we have  $\expec{}{\abs{S_B}}= N\cdot \prob{\text{Bob succeeds}} \leq \frac{2^{c'}}{\delta}$. Using Markov's inequality, 
\begin{equation} \prob{\abs{S_B} \geq \frac{2^{c'}}{\delta{\varepsilon}}}\leq \frac{\delta{\varepsilon}}{2^{c'}} \cdot \expec{}{\abs{S_B}} \leq {\varepsilon} . 
\end{equation}

    Thus
    \begin{align*}
    \prob{T_3} & \leq\prob{\abs{S_B}\geq \frac{2^{c'}}{\delta{\varepsilon}} \text{ or } m \notin S_B} +  \prob{T_3~|~m \in S_B \text{ and } \abs{S_B}\leq \frac{2^{c'}}{\delta{\varepsilon}}} \\ & \leq \prob{\abs{S_B}\geq \frac{2^{c'}}{\delta{\varepsilon}}} + \prob{T_2} + \prob{T_3~|~m \in S_B \text{ and } \abs{S_B}\leq \frac{2^{c'}}{\delta{\varepsilon}}} \\
     & \leq 2 {\varepsilon}+\prob{T_3~|~m \in S_B \text{ and } \abs{S_B}\leq \frac{2^{c'}}{\delta{\varepsilon}}}  \quad \mbox{(Eq.~\eqref{eq:sb} and item 2. of this claim)}\\
     & \leq 2{\varepsilon} + 2^{- \lceil c' + \log\frac{1}{\delta}+ 2\log\frac{1}{{\varepsilon}}\rceil} \cdot \frac{2^{c'}}{\delta{\varepsilon}} \quad  \leq \quad 3 {\varepsilon}.
    \end{align*}

\end{enumerate}
\end{proof}



We bound the probability that $m\neq n$. If $m=n$, then $m$ being the first index on which Alice succeeds, we have $m=n=j$. 

\bigskip

\noindent{\em Proof of Claim\ref{claim:highprobindex}}.\quad We conclude the claim since,
$$\prob{n \neq m} \leq\prob{T_1}+\prob{\neg T_1}\cdot\prob{T_3}\leq 4{\varepsilon}.$$ \qed

From claims \ref{claim:successprob},\ref{claim:relativeprob} and \ref{claim:highprobindex}, the probability that Bob learns the index $j$ is atleast $1-4{\varepsilon}$. Conditioned on this event, Claim \ref{claim:boboutput}, implies that the state $\rho' \in \mathcal{D}(B^j)$ that Bob outputs satisfies $\mathrm{F}(\rho',\rho)\geq 1-{\varepsilon}$. Conditioned on the event that Bob learns the wrong index or the protocol is aborted, let the state output by Bob be $\mu$. Then Bob outputs the state $\tilde{\rho}=\alpha\rho'+(1-\alpha)\mu$, where $\alpha\geq 1-4{\varepsilon}$. Using concavity of fidelity (Fact \ref{fact:fidconcave}), we have $\mathrm{F}(\tilde{\rho},\rho)\geq \alpha\mathrm{F}(\rho',\rho)+(1-\alpha)\mathrm{F}(\mu,\rho) \geq (1-4{\varepsilon})(1-{\varepsilon})\geq 1- 5{\varepsilon}$. 

The communication cost of above protocol is $$\lceil\log\log\frac{1}{{\varepsilon}}\rceil+\lceil c' + \log\frac{1}{\delta} + 2\log\frac{1}{{\varepsilon}}\rceil\leq \lceil 3^4\frac{c+2}{{\varepsilon}^4}+7\log\frac{1}{{\varepsilon}} \rceil.$$ This completes the proof of theorem.

Define $R_{ij}\ensuremath{ \stackrel{\mathrm{def}}{=} } a_i \abs{\braket{a_i}{g_j}}^2$ and $R'_{ij}\ensuremath{ \stackrel{\mathrm{def}}{=} } g_i \abs{\braket{a_i}{g_j}}^2$. Note that both $R \ensuremath{ \stackrel{\mathrm{def}}{=} } \{R_{ij}\}$ and $R' \ensuremath{ \stackrel{\mathrm{def}}{=} } \{R'_{ij}\}$ form probability distributions over $[N^2]$. Also note that $\mathrm{F}(R,R') = \ensuremath{ \mathrm{Tr} }(\sqrt{\rho}\sqrt{\rho'})$. Consider
\begin{align*}
 \abs{\braket{S_A(\rho)}{S_A(\rho')}} & =\sum_{i,j}\min(R_{ij},R'_{i,j}) = 1 - \frac{1}{2}\onenorm{R-R'} \nonumber\\
 & \geq 1 - \sqrt{1-\mathrm{F}(R,R')^2} = 1 - \sqrt{1-(\ensuremath{ \mathrm{Tr} } \sqrt{\rho}\sqrt{\rho'})^2} \nonumber \\
 & \geq 1 - \sqrt{2(1- \ensuremath{ \mathrm{Tr} } \sqrt{\rho}\sqrt{\rho'})} \geq  1- \sqrt{2 \sqrt{1-\mathrm{F}(\rho,\rho')^2}}  \nonumber \\
 & \geq 1- 2 (1-\mathrm{F}(\rho,\rho'))^{1/4} . \tag*{\qedhere} 
  \end{align*}
where the first equality is from the definitions of $\ket{S_A(\rho)}$ and $\ket{S_A(\rho')}$; the second equality is from the definition of $\ell_1$ distance; the first inequality is from ~\ref{fact:tracefidelityequi}; the second inequality is from the fact that $\ensuremath{ \mathrm{Tr} }\sqrt{\rho}\sqrt{\rho'}\leq 1$; the third inequality is from Facts~\ref{fact:fidelityvstrace}.

Consider,
\begin{equation*}
(I_A\otimes P_B)\ket{S_A(\rho')} = \frac{1}{\sqrt{K}}\sum_{i,j=1}^N\ket{\conjugate{g_j}} \ket{b_i}\braket{b_i}{g_j} \left(\sum_{m=1}^{\min\{\lceil Kg_j\rceil, \frac{K}{\delta} 2^{c'}b_i\}}\ket{m, m} \right).
\end{equation*}
Therefore,
\begin{align}
& \norm{(I_A\otimes P_B)\ket{S_A(\rho')} }^2 \geq \sum_{i,j=1}^N \abs{\braket{b_i}{g_j}}^2 \min\{g_j, \frac{1}{\delta}2^{c'}b_i \} \nonumber \\
& \geq \sum_{j=1}^N g_j \left(\sum_{i|~b_i\geq \delta 2^{-c'}g_j} \abs{\braket{b_i}{g_j}}^2 \right) \geq \sum_{j=1}^N g_j(1- \delta) = 1- \delta  . \quad \mbox{(using Claim~\ref{claim:1})} \end{align}
Using the above,

\begin{align*}
& \prob{\text{Bob succeeds}|~\text{Alice succeeds}}  =  \ensuremath{ \mathrm{Tr} } (I_A\otimes P_B)\ketbra{S_A(\rho)} \\
& \geq  \ensuremath{ \mathrm{Tr} } (I_A\otimes P_B)\ketbra{S_A(\rho')}  - \frac{1}{2} \onenorm{S_A(\rho) - S_A(\rho')} \\
& = \ensuremath{ \mathrm{Tr} } (I_A\otimes P_B)\ketbra{S_A(\rho')}  -  \sqrt{1- \abs{\braket{S_A(\rho)}{S_A(\rho')}}^2} \quad \mbox{(Fact~\ref{fact:tracefidelityequi})} \\
& \geq  1 -  \delta  - 2  \sqrt{ (1-\mathrm{F}(\rho,\rho'))^{1/2}}  . \quad \mbox{(Claim~\ref{claim:2} and Eq.~\eqref{eq:probonrho'})}
\end{align*}

\begin{itemize}

\item $T_1$ is the event that Alice does not succeed on any of the indices.

\item $T_2$ is the event that $m \notin S_B$ conditioned on $\neg T_1$ .
\item $T_3$ represents the event that $n \neq m$ conditioned on $\neg T_1$.
\end{itemize}

\begin{enumerate}

\item $\prob{T_1}\leq\br{1-\frac{1}{N}}^{\lceil N \cdot \log\frac{1}{{\varepsilon}}\rceil}\leq \exp^{-\lceil\log\frac{1}{{\varepsilon}}\rceil}\leq  \delta$.

\item Follows from Claim \ref{claim:relativeprob}.

\item For this argument we condition on $\neg T_1$ for all events below. From Claim \ref{claim:successprob} and the fact that Bob independently measures each index, we have  $\expec{}{\abs{S_B}}= N\cdot \prob{\text{Bob succeeds}} \leq \frac{2^{c'}}{\delta}$. Using Markov's inequality, 
\begin{equation} \prob{\abs{S_B} \geq \frac{2^{c'}}{\delta{\varepsilon}}}\leq \frac{\delta{\varepsilon}}{2^{c'}} \cdot \expec{}{\abs{S_B}} \leq {\varepsilon} . 
\end{equation}

    Thus
    \begin{align*}
    \prob{T_3} & \leq\prob{\abs{S_B}\geq \frac{2^{c'}}{\delta{\varepsilon}} \text{ or } m \notin S_B} +  \prob{T_3~|~m \in S_B \text{ and } \abs{S_B}\leq \frac{2^{c'}}{\delta{\varepsilon}}} \\ & \leq \prob{\abs{S_B}\geq \frac{2^{c'}}{\delta{\varepsilon}}} + \prob{T_2} + \prob{T_3~|~m \in S_B \text{ and } \abs{S_B}\leq \frac{2^{c'}}{\delta{\varepsilon}}} \\
     & \leq 2 {\varepsilon}+\prob{T_3~|~m \in S_B \text{ and } \abs{S_B}\leq \frac{2^{c'}}{\delta{\varepsilon}}}  \quad \mbox{(Eq.~\eqref{eq:sb} and item 2. of this claim)}\\
     & \leq 2{\varepsilon} + 2^{- \lceil c' + \log\frac{1}{\delta}+ 2\log\frac{1}{{\varepsilon}}\rceil} \cdot \frac{2^{c'}}{\delta{\varepsilon}} \quad  \leq \quad 3 {\varepsilon}.
    \end{align*}

\end{enumerate}

Let $\rho,\sigma$ be quantum states on a Hilbert space $\CMcal{H}$ of dimension $N$. Alice is given the eigen-decomposition of $\rho$ and Bob is given the eigen-decomposition of $\sigma$.  There exists a zero-communication  protocol satisfying the following.
\begin{enumerate}
\item Alice outputs registers  $A_1,A_2$ and and Bob outputs registers $B_1,B_2$ respectively, such that state in $A_1$ is $\rho$, the state in $B_1$ is $\sigma$ and $A_1\equiv B_1, A_2\equiv B_2$.
\item Let $M = \{M_1,M_2\ldots M_w\}$ be a projective measurement, in the support of $A_1A_2$. Let $M$ be performed by Alice on the joint system $A_1A_2$ with outcome $I \in [w]$ and by Bob on the joint system $B_1B_2$ with outcome $J \in [w]$. Then $\Pr[I = J] \geq \left(1-\sqrt{\onenorm{\rho-\sigma} - \frac{1}{4}\onenorm{\rho-\sigma}^2}\right)^{3}$. 
\end{enumerate}

Let eigen-decomposition of $\rho$ be $\sum_{i=1}^Na_i\ketbra{a_i}$ and of $\sigma$ be $\sum_{i=1}^Nb_i\ketbra{b_i}$. Let $\set{\ket{1},\ket{2}\ldots \ket{N}}$ be an orthonormal basis for $\CMcal{H}$. We assume that $a_1, \ldots, a_N, b_1,  \ldots b_N$ are rational numbers and let $K$ be the least common multiple of their denominators. The error due to this assumption goes to $0$ as $K \rightarrow \infty$. 

Introduce registers $A_1,B_1$ associated to $\CMcal{H}$ and registers $A_2,B_2$ associated to some Hilbert space $\CMcal{H}'$ with an orthonormal basis $\set{\ket{1},\ket{2}\ldots \ket{K}}$.

Consider the following state shared in $A_1,A_2,B_1,B_2$.
\begin{equation*}
\ket{S}_{A_1B_1A_2B_2} \ensuremath{ \stackrel{\mathrm{def}}{=} } \frac{1}{\sqrt{KN}}\sum_{i=1}^N \ket{i,i}_{A_1B_1} \otimes \left(\sum_{m=1}^{K}\ket{m, m}_{A_2B_2} \right)
\end{equation*}

 For brevity, define the registers $A\ensuremath{ \stackrel{\mathrm{def}}{=} } A_1A_2$ and $B \ensuremath{ \stackrel{\mathrm{def}}{=} } B_1B_2$. The protocol is described below.
\begin{mdframed}
\bigskip
\textbf{Input:} Alice is given $\rho=\sum_{i=1}^Na_i\ketbra{a_i}$. Bob is given $\sigma=\sum_{i=1}^Nb_i\ketbra{b_i}$.
\bigskip

\textbf{Shared resources:} Alice and Bob hold infinitely many registers $A_1^iA_2^iB_1^iB_2^i$ ($i>0$), such that $A_1^i\equiv A_1, A^i_2\equiv A_2, B_1^i\equiv B_1,B_2^i\equiv B_2$. The shared state in register $A_1^iA_2^iB_1^iB_2^i$ is $\ket{S}_{A_1^iA_2^iB_1^iB_2^i}$. Let $A \equiv A_1A_2$ and $B\equiv B_1B_2$ be used as output registers. Let $i$ refer to the `index' of corresponding registers.

\begin{enumerate}

\item For each $i>0$, Alice performs the measurement $\set{P_A,I- P_A}$ on the registers $A^i_1A^i_2$, where
\begin{equation*}
P_A\ensuremath{ \stackrel{\mathrm{def}}{=} }\sum_i\ket{a_i}_{A_1}\bra{a_i}_{A_1}\otimes \left(\sum_{m=1}^{Ka_i}\ket{m}_{A_2}\bra{m}_{A_2}\right)
\end{equation*}

She declares \textit{success} if she obtains outcome corresponding to $P_A$. She stops once she succeeds in some register $A^j$, and swaps $A^j$ with $A$. 

\item For each $i>0$, Bob performs the measurement $\set{P_B,I- P_B}$ on the registers $B^i_1B^i_2$, where
\begin{equation*}
P_B\ensuremath{ \stackrel{\mathrm{def}}{=} }\sum_i\ket{b_i}_{B_1}\bra{b_i}_{B_1}\otimes \left(\sum_{m=1}^{Kb_i}\ket{m}_{B_2}\bra{m}_{B_2}\right)
\end{equation*}

He declares \textit{success} if he obtains outcome corresponding to $P_B$. He stops once he succeeds in some register $B^j$, and swaps $B^j$ with $B$.

\end{enumerate}

\end{mdframed}
\bigskip

At the end of above protocol, let the joint state in the register $AB$ be $\tau$. The following claim shows the first part of the theorem. 
\begin{claim} $\ensuremath{ \mathrm{Tr} }_{A_2B_1B_2}(\tau)=\rho$ and $\ensuremath{ \mathrm{Tr} }_{A_1A_2B_2}(\tau)=\sigma$.
\end{claim}
\begin{proof}
It is easily seen that the marginal of the state $(P_A \otimes I_B) \ket{S}$ in register $A$  is $\rho$. Similarly the marginal of the state $(I_A \otimes P_B) \ket{S}$ in register $B$ in  is $\sigma$.
\end{proof}

Following series of claims establish second part of the theorem.
\begin{claim} \begin{equation*}
\tau \geq \frac{(P_A\otimes P_B)\ket{S}\bra{S}(P_A\otimes P_B) }{1 - \bra{S} (I_A-P_A)\otimes(I_B-P_B)\ket{S}} \enspace .
\end{equation*}
\end{claim}
\begin{proof}
Consider the event that Alice and Bob succeed at the same index. The resulting state in $AA_1BB_1$ is 
$$\frac{(P_A\otimes P_B ) \ket{S}\bra{S} (P_A\otimes P_B)}{\bra{S}(P_A \otimes P_B)\ket{S}},$$ 
and this event occurs with probability 
$$\sum_{i=0}^{\infty}\bra{S}(I_A-P_A)\otimes(I_B-P_B)\ket{S}^{i} \cdot \bra{S}(P_A \otimes P_B)\ket{S}= \frac{\bra{S}(P_A \otimes P_B)\ket{S}}{1 - \bra{S}(I_A-P_A)\otimes(I_B-P_B)\ket{S}}.$$ 
Since the cases of Bob succeeding before Alice and Alice succeeding before Bob add positive operators to $\tau$, we get the desired.  
\end{proof}

\begin{claim} Let $\ket{\theta} \ensuremath{ \stackrel{\mathrm{def}}{=} } \frac{(P_A\otimes P_A)\ket{S}}{\norm{(P_A\otimes P_A)\ket{S}}}$. Then 
$$\bra{\theta}\tau\ket{\theta} \geq \frac{\left(1-\sqrt{\onenorm{\rho-\sigma} - \frac{1}{4}\onenorm{\rho-\sigma}^2}\right)^2}{1 + \sqrt{\onenorm{\rho-\sigma} - \frac{1}{4}\onenorm{\rho-\sigma}^2}} \geq \left(1-\sqrt{\onenorm{\rho-\sigma} - \frac{1}{4}\onenorm{\rho-\sigma}^2}\right)^3 .$$ 
\end{claim}
\begin{proof}
Consider,
\begin{align*}
\bra{\theta}\tau\ket{\theta} &\geq   \frac{ \abs{\bra{\theta}P_A\otimes P_B\ket{S}}^2}{1 - \bra{S} (I_A-P_A)\otimes(I_B-P_B)\ket{S}} &  \mbox{(Claim~\ref{claim:tau})}\\ 
& = \frac{ \abs{\bra{\theta}P_A\otimes P_B\ket{S}}^2}{2/N-\bra{S}P_A\otimes P_B\ket{S}} & \mbox{(using $\bra{S}P_A\otimes I_B\ket{S}=\bra{S}I_A\otimes P_B\ket{S}=1/N$)}.
\end{align*}

By direct calculation, we get 
$$(P_A\otimes P_B)\ket{S}=\frac{1}{\sqrt{KN}}\sum_{i,j}\ket{\conjugate{a_i}}\braket{b_j}{a_i}\ket{b_j}\sum_{m=1}^{K\min(a_i,b_j)}\ket{m,m} ;$$ 
$$\ket{\theta}=\frac{1}{\sqrt{K}}\sum_i\ket{\conjugate{a_i}}\ket{a_i}\sum_{m=1}^{Ka_i}\ket{m,m} .$$ 
Hence,
\begin{equation} \bra{\theta}\tau\ket{\theta} \geq \frac{\left(\sum_{i,j}\min(a_i,b_j) \abs{\braket{a_i}{b_j}}^2\right)^2}{2-\sum_{i,j}\min(a_i,b_j) \abs{\braket{a_i}{b_j}}^2} .
\end{equation}

Define $R_{ij}\ensuremath{ \stackrel{\mathrm{def}}{=} } a_i \abs{\braket{a_i}{b_j}}^2$ and $R'_{ij}\ensuremath{ \stackrel{\mathrm{def}}{=} } b_i \abs{\braket{a_i}{b_j}}^2$. Note that both $\{R_{ij}\}$ and $\{R'_{ij}\}$ form probability distributions over $[N^2]$. Also note that $\mathrm{F}(R,R') = \ensuremath{ \mathrm{Tr} }(\sqrt{\rho}\sqrt{\sigma})$. Consider (using relation between fidelity and $\ell_1$ distance, Facts~\ref{fact:fidelityvstrace} and~\ref{fact:tracefidelityequi}),
\begin{align}
 \sum_{i,j}\min(R_{ij},R'_{i,j}) & = 1 - \frac{1}{2}\onenorm{R-R'}  \geq 1 - \sqrt{1-\mathrm{F}(R,R')^2} \nonumber \\
 &= 1 - \sqrt{1-(\ensuremath{ \mathrm{Tr} } \sqrt{\rho}\sqrt{\sigma})^2}  \geq  1-\sqrt{\onenorm{\rho-\sigma} - \frac{1}{4}\onenorm{\rho-\sigma}^2} . 
  \end{align}
  Combining Equations~\eqref{eq:thetatau} and~\eqref{eq:minR} we get the desired.
\end{proof}


\begin{claim}
Let $M=\{M_1,M_2\ldots M_w\}$ be a projective measurement  in the support of $A_1A_2$. Let $E=\sum_{i=1}^w M_i\otimes M_i$. Then $\ensuremath{ \mathrm{Tr} } (E \ketbra{\theta}) = 1$.
\end{claim}

\begin{proof}
Since $M_i$ is a projector in the support of $A_1A_2$, we have $(M_i\otimes M_i)\ket{\theta} = (M_i\otimes I)\ket{\theta}$. Hence, \[\bra{\theta}E\ket{\theta}=\sum_i\bra{\theta}M_i\otimes M_i\ket{\theta} = \sum_i\bra{\theta}M_i\otimes I\ket{\theta} = 1 . \tag*{\qedhere} \]
\end{proof}
Finally  using monotonicity of fidelity under quantum operation (Fact~\ref{fact:monotonequantumoperation}) and Claim~\ref{overlaptau} we get the second part of the theorem as follows. 
\[\sqrt{\ensuremath{ \mathrm{Tr} } (E\tau)} \geq  \mathrm{F}(\tau , \ketbra{\theta}) = \sqrt{\bra{\theta}\tau\ket{\theta}} \geq \left(1-\sqrt{\onenorm{\rho-\sigma} - \frac{1}{4}\onenorm{\rho-\sigma}^2}\right)^{3/2} . \tag*{\qedhere} \]

\begin{equation*}
\tau \geq \frac{(P_A\otimes P_B)\ket{S}\bra{S}(P_A\otimes P_B) }{1 - \bra{S} (I_A-P_A)\otimes(I_B-P_B)\ket{S}} \enspace .
\end{equation*}

